-- Jordan: milestone translations (es/de/fr).

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-launch', 'es', 'Se lanza JoFotara — el Sistema Nacional de Facturación Electrónica de Jordania', 'El Departamento de Impuesto sobre la Renta y las Ventas (ISTD), junto con el Ministerio de Economía Digital y Emprendimiento, lanzó JoFotara, una plataforma centralizada de facturación electrónica, con carácter voluntario. Las empresas podían empezar a registrarse e integrarse antes de las fases obligatorias que siguieron.', '["No se requiere ninguna acción todavía, salvo que el ISTD ya haya contactado con su empresa sobre el registro anticipado", "Los grandes contribuyentes deben empezar a seguir las comunicaciones del ISTD, ya que la incorporación de la Fase 1 llega en pocas semanas"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-launch', 'de', 'JoFotara — Jordaniens nationales elektronisches Rechnungssystem — startet', 'Die Einkommen- und Umsatzsteuerbehörde (ISTD) startete zusammen mit dem Ministerium für digitale Wirtschaft und Unternehmertum JoFotara, eine zentralisierte E-Rechnungsplattform, auf freiwilliger Basis. Unternehmen konnten sich bereits vor den folgenden verpflichtenden Phasen registrieren und integrieren.', '["Noch keine Maßnahme erforderlich, außer die ISTD hat Ihr Unternehmen bereits zur frühzeitigen Registrierung kontaktiert", "Große Steuerzahler sollten die Kommunikation der ISTD verfolgen, da die Phase-1-Einführung innerhalb weniger Wochen folgt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-launch', 'fr', 'Lancement de JoFotara — le système national de facturation électronique de la Jordanie', 'Le Département des impôts sur le revenu et des ventes (ISTD), avec le ministère de l''Économie numérique et de l''Entrepreneuriat, a lancé JoFotara, une plateforme centralisée de facturation électronique, sur une base volontaire. Les entreprises pouvaient commencer à s''enregistrer et à s''intégrer avant les phases obligatoires qui ont suivi.', '["Aucune action requise pour l''instant, sauf si l''ISTD a déjà contacté votre entreprise au sujet d''un enregistrement anticipé", "Les grands contribuables doivent commencer à surveiller les communications de l''ISTD, la mise en place de la Phase 1 suivant dans quelques semaines"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-phase1', 'es', 'Fase 1 — comienza la incorporación obligatoria para los grandes contribuyentes', 'El registro e integración con JoFotara se convirtió en obligatorio para los grandes contribuyentes de Jordania, el primer grupo que debía dejar de participar de forma voluntaria. Las facturas se validan a través de JoFotara en tiempo real — un modelo de validación centralizada, no de reporte posterior — con un código QR emitido por el ISTD que confirma la validación.', '["Si es un gran contribuyente, confirme su estado de registro e integración directamente con el ISTD", "Elija una vía de integración: API directa, el portal web gratuito de JoFotara, o un proveedor de servicios certificado"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-phase1', 'de', 'Phase 1 — verpflichtende Einführung beginnt für Großsteuerzahler', 'Die Registrierung und Integration mit JoFotara wurde für Jordaniens Großsteuerzahler verpflichtend — die erste Gruppe, die von freiwilliger Teilnahme abrücken musste. Rechnungen werden über JoFotara in Echtzeit geprüft — ein zentralisiertes Clearing-Modell, keine nachträgliche Meldung — mit einem von der ISTD ausgestellten QR-Code, der die Validierung bestätigt.', '["Wenn Sie ein Großsteuerzahler sind, bestätigen Sie Ihren Registrierungs- und Integrationsstatus direkt bei der ISTD", "Wählen Sie einen Integrationsweg: direkte API, das kostenlose JoFotara-Webportal oder einen zertifizierten Drittanbieter"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-phase1', 'fr', 'Phase 1 — l''intégration obligatoire commence pour les grands contribuables', 'L''enregistrement et l''intégration à JoFotara sont devenus obligatoires pour les grands contribuables de Jordanie, le premier groupe tenu de quitter la participation volontaire. Les factures sont validées via JoFotara en temps réel — un modèle de validation centralisée, non un reporting a posteriori — avec un code QR émis par l''ISTD confirmant la validation.', '["Si vous êtes un grand contribuable, confirmez votre statut d''enregistrement et d''intégration directement auprès de l''ISTD", "Choisissez une méthode d''intégration : API directe, portail web gratuit de JoFotara, ou prestataire de services certifié"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-universal-registration', 'es', 'Plazo de registro universal — todos los contribuyentes registrados a efectos del IVA', 'La ola de incorporación que comenzó con los grandes contribuyentes en la Fase 1 se completó: toda empresa y persona registrada a efectos del IVA (sin exención para pymes o pequeños negocios) debía estar registrada e integrada con JoFotara antes de esta fecha, antes de la plena aplicación legal al año siguiente.', '["Confirme que su empresa está registrada en JoFotara si aún no estaba cubierta por la Fase 1", "Las pymes y los profesionales independientes (p. ej., consultores) sin sistemas propios pueden registrarse gratis a través del portal web de JoFotara"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-universal-registration', 'de', 'Frist für die universelle Registrierung — alle umsatzsteuerpflichtigen Steuerzahler', 'Die mit den Großsteuerzahlern in Phase 1 begonnene Einführungswelle wurde abgeschlossen: Jedes umsatzsteuerpflichtige Unternehmen und jede Einzelperson (ohne Ausnahme für KMU oder Kleinunternehmen) musste bis zu diesem Datum bei JoFotara registriert und integriert sein, vor der vollständigen rechtlichen Durchsetzung im folgenden Jahr.', '["Bestätigen Sie, dass Ihr Unternehmen bei JoFotara registriert ist, falls es nicht bereits unter Phase 1 fiel", "KMU und selbstständige Fachleute (z. B. Berater) ohne eigene Systeme können sich kostenlos über das JoFotara-Webportal registrieren"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-universal-registration', 'fr', 'Échéance d''enregistrement universel — tous les contribuables assujettis à la TVA', 'La vague d''intégration entamée avec les grands contribuables en Phase 1 s''est achevée : toute entreprise et personne assujettie à la TVA (sans exemption pour les PME ou petites entreprises) devait être enregistrée et intégrée à JoFotara avant cette date, en amont de la pleine application légale l''année suivante.', '["Confirmez que votre entreprise est enregistrée auprès de JoFotara si elle n''était pas déjà couverte par la Phase 1", "Les PME et les professionnels indépendants (p. ex. consultants) sans systèmes internes peuvent s''enregistrer gratuitement via le portail web de JoFotara"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-phase2', 'es', 'Fase 2 — plena aplicación en B2B, B2G y B2C', 'La validación a través de JoFotara se volvió obligatoria en la práctica, no solo en el registro, para todas las transacciones nacionales B2B, B2G y B2C, además del comercio transfronterizo de los contribuyentes residentes. Una factura no transmitida a través de JoFotara no es válida para la deducción del IVA soportado ni a efectos contables — el verdadero motor de aplicación del mandato.', '["Verifique que todos los canales de venta pasen por JoFotara antes de emitir facturas, incluidos el punto de venta y el comercio electrónico", "Confirme que las facturas de sus clientes lleven un código QR válido emitido por el ISTD antes de basarse en ellas para la deducción del IVA"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-phase2', 'de', 'Phase 2 — vollständige Durchsetzung für B2B, B2G und B2C', 'Die Validierung über JoFotara wurde in der Praxis verpflichtend, nicht nur bei der Registrierung, für alle inländischen B2B-, B2G- und B2C-Transaktionen sowie den grenzüberschreitenden Handel gebietsansässiger Steuerzahler. Eine nicht über JoFotara übermittelte Rechnung ist für den Vorsteuerabzug und buchhalterische Zwecke ungültig — der eigentliche Durchsetzungsmotor der Pflicht.', '["Stellen Sie sicher, dass jeder Vertriebskanal vor der Rechnungsstellung über JoFotara läuft, einschließlich POS und E-Commerce", "Bestätigen Sie, dass die Rechnungen Ihrer Kunden einen gültigen, von der ISTD ausgestellten QR-Code tragen, bevor Sie sich für den Vorsteuerabzug darauf verlassen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-phase2', 'fr', 'Phase 2 — application intégrale pour le B2B, le B2G et le B2C', 'La validation via JoFotara est devenue obligatoire dans la pratique, pas seulement pour l''enregistrement, pour toutes les transactions nationales B2B, B2G et B2C, ainsi que pour le commerce transfrontalier des contribuables résidents. Une facture non transmise via JoFotara n''est pas valable pour la déduction de la TVA en amont ni à des fins comptables — le véritable moteur d''application de l''obligation.', '["Vérifiez que chaque canal de vente passe par JoFotara avant d''émettre des factures, y compris les points de vente et le commerce électronique", "Confirmez que les factures de vos clients portent un code QR valide émis par l''ISTD avant de vous y fier pour la déduction de la TVA"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-penalty-grace-end', 'es', 'Expira el periodo de gracia para la exención de sanciones', 'Un periodo de gracia que eximía de las multas acumuladas a las empresas que se registraron tarde se cerró en esta fecha. A partir de aquí, se aplica el régimen sancionador completo sin excepción: multas de aproximadamente JOD 500 por infracción según el Reglamento de Facturación y Control, que escalan hasta prisión (3-6 meses) o multas de hasta JOD 1.000 por incumplimiento persistente, además de la exclusión de las licitaciones públicas.', '["Regístrese de inmediato si aún no lo ha hecho — la exención de multas ya no está disponible", "Revise las facturas anteriores en busca de deficiencias de cumplimiento con JoFotara antes de que una auditoría del ISTD las detecte primero"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-penalty-grace-end', 'de', 'Kulanzfrist für den Bußgelderlass läuft aus', 'Eine Kulanzfrist, in der aufgelaufene Bußgelder für Unternehmen erlassen wurden, die sich verspätet registrierten, endete an diesem Datum. Ab jetzt gilt das vollständige Bußgeldregime ohne Ausnahme: Bußgelder von etwa JOD 500 pro Verstoß gemäß der Abrechnungs- und Kontrollverordnung, die sich bei anhaltender Nichteinhaltung auf Freiheitsstrafe (3-6 Monate) oder Bußgelder bis zu JOD 1.000 steigern, zuzüglich Ausschluss von öffentlichen Ausschreibungen.', '["Registrieren Sie sich sofort, falls noch nicht geschehen — der Bußgelderlass steht nicht mehr zur Verfügung", "Überprüfen Sie frühere Rechnungen auf JoFotara-Compliance-Lücken, bevor eine ISTD-Prüfung sie zuerst findet"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('jo-penalty-grace-end', 'fr', 'Expiration du délai de grâce pour la remise des sanctions', 'Un délai de grâce exonérant des amendes accumulées les entreprises enregistrées tardivement a pris fin à cette date. Désormais, le régime de sanctions complet s''applique sans exception : amendes d''environ 500 JOD par infraction selon le règlement sur la facturation et le contrôle, pouvant aller jusqu''à une peine d''emprisonnement (3-6 mois) ou des amendes allant jusqu''à 1 000 JOD en cas de non-conformité persistante, ainsi que l''exclusion des marchés publics.', '["Enregistrez-vous immédiatement si ce n''est pas déjà fait — la remise des amendes n''est plus disponible", "Vérifiez les factures passées pour détecter les lacunes de conformité JoFotara avant qu''un contrôle de l''ISTD ne les détecte en premier"]');
